using Microsoft.EntityFrameworkCore;
using System.Text.Json;
namespace Society.Api;
public class UnifiedReportWorker(IServiceScopeFactory factory,ILogger<UnifiedReportWorker> log):BackgroundService {
 protected override async Task ExecuteAsync(CancellationToken ct){while(!ct.IsCancellationRequested){var worked=false;try{using var scope=factory.CreateScope();worked=await Process(scope.ServiceProvider,ct);}catch(Exception e)when(!ct.IsCancellationRequested){log.LogWarning("Unified reporting pass failed: {Type}",e.GetType().Name);}if(!worked)try{await Task.Delay(1000,ct);}catch(OperationCanceledException){break;}}}
 internal static UnifiedIntelligence Context(AppDb db,Access access,FinanceService finance)=>new(db,access,new CommunityService(db,access),finance,new ServiceProjectService(db,access,new CommunityService(db,access)));
 static async Task<bool> Process(IServiceProvider services,CancellationToken ct){var db=services.GetRequiredService<AppDb>();var config=services.GetRequiredService<IConfiguration>();await using var tx=await db.Database.BeginTransactionAsync(ct);var schedules=await db.Set<UnifiedReportSchedule>().FromSqlRaw("SELECT * FROM \"UnifiedReportSchedule\" WHERE \"Enabled\"=true AND \"NextRun\"<=now() ORDER BY \"NextRun\" LIMIT 1 FOR UPDATE SKIP LOCKED").ToListAsync(ct);var schedule=schedules.FirstOrDefault();if(schedule!=null){var (access,finance,_)=FinanceWorker.Context(db,schedule.AuthorId,config);try{if(!await PlatformPolicy.WorkAllowed(db,schedule.TenantId,"intelligence"))throw new AccessDeniedException();await access.Require(schedule.TenantId,"reports.schedule",schedule.UnitId);var report=await db.Set<SavedUnifiedReport>().SingleAsync(r=>r.TenantId==schedule.TenantId&&r.Id==schedule.ReportId&&r.AuthorId==schedule.AuthorId,ct);var request=JsonSerializer.Deserialize<UnifiedReportRequest>(report.Definition,DesignSchema.Json)! with{Format=schedule.Format};await Context(db,access,finance).Report(schedule.TenantId,request);var key="schedule:"+schedule.Id+":"+schedule.NextRun.ToUnixTimeSeconds();if(!await db.Set<StudioJob>().AnyAsync(j=>j.TenantId==schedule.TenantId&&j.AuthorId==schedule.AuthorId&&j.Key==key,ct))db.Add(new StudioJob{TenantId=schedule.TenantId,UnitId=schedule.UnitId,AuthorId=schedule.AuthorId,Kind="Report",Key=key,Payload=JsonSerializer.Serialize(request,DesignSchema.Json),State="Queued"});schedule.NextRun=schedule.Frequency=="Monthly"?DateTimeOffset.UtcNow.AddMonths(1):DateTimeOffset.UtcNow.AddDays(schedule.Frequency=="Weekly"?7:1);schedule.LastError="";}catch(Exception e)when(e is AccessDeniedException or DomainException){schedule.Enabled=false;schedule.LastError=e is DomainException?e.Message:"Current report authority is insufficient";}await db.SaveChangesAsync(ct);await tx.CommitAsync(ct);return true;}
  var jobs=await db.Set<StudioJob>().FromSqlRaw("SELECT * FROM \"StudioJob\" WHERE \"Kind\"='Report' AND \"State\"='Queued' ORDER BY \"At\" LIMIT 1 FOR UPDATE SKIP LOCKED").ToListAsync(ct);var job=jobs.FirstOrDefault();if(job==null){await tx.CommitAsync(ct);return false;}var (a,fin,_comm)=FinanceWorker.Context(db,job.AuthorId,config);try{if(!await PlatformPolicy.WorkAllowed(db,job.TenantId,"intelligence"))throw new AccessDeniedException();var request=JsonSerializer.Deserialize<UnifiedReportRequest>(job.Payload,DesignSchema.Json)!;var store=services.GetRequiredService<IObjectStore>();var bytes=await Context(db,a,fin).Export(job.TenantId,request,services.GetRequiredService<FinanceDocuments>());job.FileId=Guid.NewGuid();await store.Put(job.TenantId,job.FileId.Value,bytes);job.ContentType=request.Format=="pdf"?"application/pdf":request.Format=="xlsx"?"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet":"text/csv";job.State="Completed";job.CompletedAt=DateTimeOffset.UtcNow;job.Processed=1;await db.SaveChangesAsync(ct);await tx.CommitAsync(ct);}catch(Exception e)when(e is AccessDeniedException or DomainException or IOException or DbUpdateException){await tx.RollbackAsync(ct);db.ChangeTracker.Clear();job=await db.Set<StudioJob>().SingleAsync(j=>j.Id==job.Id,ct);job.State="Failed";job.Error=e is DomainException?e.Message:"Current source/report authority or storage does not permit generation";await db.SaveChangesAsync(ct);}return true;
 }
}
